!function(t){function r(r){for(var i,n,o=r[0],s=r[1],m=r[2],c=0,l=[];c<o.length;c++)n=o[c],Object.prototype.hasOwnProperty.call(a,n)&&a[n]&&l.push(a[n][0]),a[n]=0;for(i in s)Object.prototype.hasOwnProperty.call(s,i)&&(t[i]=s[i]);for(u&&u(r);l.length;)l.shift()();return p.push.apply(p,m||[]),e()}function e(){for(var t,r=0;r<p.length;r++){for(var e,n=p[r],o=!0,s=1;s<n.length;s++)e=n[s],0!==a[e]&&(o=!1);o&&(p.splice(r--,1),t=i(i.s=n[0]))}return t}function i(r){if(n[r])return n[r].exports;var e=n[r]={i:r,l:!1,exports:{}};return t[r].call(e.exports,e,e.exports,i),e.l=!0,e.exports}var n={},a={15:0},p=[];i.m=t,i.c=n,i.d=function(t,r,e){i.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:e})},i.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},i.t=function(t,r){if(1&r&&(t=i(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var e=Object.create(null);if(i.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var n in t)i.d(e,n,function(r){return t[r]}.bind(null,n));return e},i.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return i.d(r,"a",r),r},i.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},i.p="";var o=window.webpackJsonp=window.webpackJsonp||[],s=o.push.bind(o);o.push=r,o=o.slice();for(var m=0;m<o.length;m++)r(o[m]);var u=s;p.push([71,0]),e()}({71:function(t,r,e){"use strict";e.r(r);var i=e(0);Object(i.a)("us","army",e(72),e(1))},72:function(t){t.exports=JSON.parse('{"category":[{"name":"美国","link":"us_shortcut"},{"name":"陆战武器","link":"us_army"},{"name":"两栖装甲车辆","link":"us_army#us_army_lvt"}],"model":"LVT4两栖装甲车","description":"<h6>综述：</h6><p>LVT4是在LVT2基础上进行改进的，在LVT系列两栖装甲车中，它的生产数量最多，达到8300多辆，比前三种型号生产的总数还要多。LVT4将发动机移向车体前方，由此腾出了较大空间车舱，可以运载吉普车和中小口径的火炮。该车除了装备机枪外，它还可以装备带一门75mm短管榴弹炮的M8自行火炮的炮塔，火力十分强劲，因此除了可作登陆人员与物资的运输，还可在海上和陆上提供火力支援。</p><p>LVT4跟随美军参加了太平洋战场与欧洲西线莱茵河战场上众多战斗，是美军两栖作战的重要装备。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/us/army/us_army_lvt4_11.jpg","description":"<h6>LVT4两栖装甲车（前期生产，非装甲型）</h6><p>自重：12.428吨，战斗全重：16.5吨；水中最大航速：12千米/小时，陆上最大车速：32千米/小时；武器配备：正面2挺M2型12.7mm重机枪，车体后部两侧也可配备2挺7.62mm机枪（下车作战时可卸下使用）。</p>","caption":""},{"image":"imgs/us/army/us_army_lvt4_12.jpg","description":"<h6>LVT4两栖装甲车（后期生产，装甲型）</h6><p>后期生产的LVT4加装了6.5mm防护装甲，部分还加装了一个带75mm短管榴弹炮的M8自行火炮的炮塔。</p>","caption":""}],"part2title":"战场上的LVT4两栖装甲车","part2description":"","part2content":[{"image":"imgs/us/army/us_army_lvt4_21.jpg","description":"1944年9月，太平洋战场，美军（不明单位）的一辆早期生产的LVT4两栖装甲车。","caption":""},{"image":"imgs/us/army/us_army_lvt4_22.jpg","description":"1944年9月，太平洋战场，美军（不明单位）的一辆LVT4两栖装甲车，该车车体后侧部加装了7.62mm口径的机枪。","caption":""},{"image":"imgs/us/army/us_army_lvt4_23.jpg","description":"1945年4月，太平洋战场冲绳岛，隶属美军第77步兵师一辆后期生产的LVT4两栖装甲车，该车已装上了带75mm短管榴弹炮的M8自行火炮炮塔。","caption":""},{"image":"imgs/us/army/us_army_lvt4_24.jpg","description":"1944年7月，太平洋战场塞班岛，隶属美军一队LVT4两栖装甲车登岛后正向岛内挺进，该车涂了特别的迷彩色，战斗实践中证明，LVT两栖装甲车由于要在水中和陆上行驶，因此车体的迷彩色必须要适应两者的环境。","caption":""},{"image":"imgs/us/army/us_army_lvt4_25.jpg","description":"1944年9月，太平洋战场佩莱利乌岛，美国士兵用配备在LVT4两栖装甲车上的火焰喷射枪向日军一洞穴据点喷射火焰。","caption":""},{"image":"imgs/us/army/us_army_lvt4_26.jpg","description":"1945年4月太平洋战场，对冲绳岛的主要进攻开始，美军出动了1400辆各型LVT两栖装甲车运送作战人员与弹药（每个师都配备了两个弹药营，通过LVT的运输来保证弹药的供应）。图中的LVT4两栖装甲车正将美军第7步兵师的士兵运送上岸。","caption":""},{"image":"imgs/us/army/us_army_lvt4_27.jpg","description":"1945年4月太平洋战场冲绳岛战役，在安装有75mm短筒火炮的LVT4两栖装甲车的火力支援下，刚登上海岛的美军士兵正在沙石掩护下作进攻准备。","caption":""},{"image":"imgs/us/army/us_army_lvt4_28.jpg","description":"1945年4月，太平洋战场冲绳岛，美军一队安装有75mm短筒火炮的LVT4两栖装甲车正向岛内战场进发。","caption":""},{"image":"imgs/us/army/us_army_lvt4_29.jpg","description":"1945年2月，在菲律宾上岸后的美军继续使用LVT4S两栖装甲车深入内陆，向马尼拉挺进，该车前板还涂上了鳄鱼大嘴的牙齿图案。","caption":""},{"image":"imgs/us/army/us_army_lvt4_30.jpg","description":"1945年4月26日，欧洲西线战场，正在水中行驶的美国一辆LVT4两栖装甲车。吸取太平洋战争的经验，为了使机枪手在操作机枪时得到保护。该辆LVT4的两挺机枪都装上了全防护钢板；车上一美军士兵向镜头竖起了胜利的“V”形手势，显示盟军已到了胜利的时刻。","caption":""},{"image":"imgs/us/army/us_army_lvt4_31.jpg","description":"1945年2月，欧洲西线战场，美国陆军309工程队不满足LVT4两栖装甲车现有的能力，将车体后部尾板改装为坡道，使LVT4能运载吉普车及其所携带的物资。图中是一辆LVT4正在荷兰一试验场地进行试载。","caption":""},{"image":"imgs/us/army/us_army_lvt4_32.jpg","description":"英国皇家第11坦克团C中队将这辆美式LVT4换装上英军典型的20mm高射机枪，并装上了带有铰链式后起落架，成为一辆改装的英式LVT4两栖装甲车。","caption":""},{"image":"imgs/us/army/us_army_lvt4_33.jpg","description":"绘图：正在水中急速行驶的美军LVT4两栖装甲车。","caption":""}]}')}});